mapper.select:
select hospital_id,name, address,phone,grade, type,medical_insurance,note from hospitals where name like concat('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT hospital_id, name, address, phone, d_grade.type_name AS grade, d_type.type_name AS type, medical_insurance, note FROM hospitals JOIN drugs_hospitals_relation d_grade ON hospitals.grade = d_grade.type_id JOIN drugs_hospitals_relation d_type ON hospitals.type = d_type.type_id WHERE d_grade.relation_type = 2 AND d_type.relation_type = 3 where grade like concat('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT hospital_id, name, address, phone, d_grade.type_name AS grade, d_type.type_name AS type, medical_insurance, note FROM hospitals JOIN drugs_hospitals_relation d_grade ON hospitals.grade = d_grade.type_id JOIN drugs_hospitals_relation d_type ON hospitals.type = d_type.type_id WHERE d_grade.relation_type = 2 AND d_type.relation_type = 3 where type like concat('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

